// Auto-generated: a realistic "coding-problem screenshot" (600x380, dark editor +
// a Two Sum prompt & snippet) used by the vision-model connectivity test — mirrors a
// real screenshot so VLMs that reject tiny images (e.g. Qwen-VL min-pixel limits) accept it.
export const VISION_PROBE_PROMPT =
  '请读取图片，依次回答三项内容：被初始化为空字典的变量名、for 循环调用的遍历函数名、题目标题。只输出答案；看不清请明确说无法识别。'

const VISION_PROBE_CODE_MARKERS = ['seen', 'enumerate'] as const

// Models often wrap OCR output in code fences/bold text or insert extra whitespace. Collapse
// formatting and punctuation while retaining letters/numbers, then require several independent
// facts from the image. The prompt deliberately does not reveal these answers, so a text-only
// model cannot pass merely by accepting the HTTP request or echoing the instruction.
export function matchesVisionProbeResponse(content: string | null | undefined): boolean {
  if (!content) return false
  const tokens: string[] =
    content
      .normalize('NFKC')
      .toLowerCase()
      .match(/[\p{L}\p{N}]+/gu) ?? []
  const hasCodeMarkers = VISION_PROBE_CODE_MARKERS.every((marker) => tokens.includes(marker))
  const hasTitle =
    tokens.includes('twosum') ||
    tokens.some((token, index) => token === 'two' && tokens[index + 1] === 'sum') ||
    tokens.includes('两数之和')
  return hasCodeMarkers && hasTitle
}

export const VISION_PROBE_PNG_B64 =
  ''
